{
  "status": "SUPPORTED",
  "task_summary": "Find tools/parts in storage, fasten the workpiece, leave tools on table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object on the table that needs to be fastened.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "fixture", "target"],
        "required_properties": ["physical", "needs fastening"]
      },
      {
        "id": "fastening_equipment",
        "entity_kind": "OBJECT",
        "function": "The tool or parts needed to perform the fastening.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["tool", "part", "screwdriver", "wrench", "bolt"],
        "required_properties": ["capable of fastening", "compatible with workpiece"]
      },
      {
        "id": "storage_unit",
        "entity_kind": "FIXED_TARGET",
        "function": "Closed containers where equipment might be hidden.",
        "required_count": 3
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "compartment"],
        "required_properties": ["closed", "has handle or latch", "holds items"]
      },
      {
        "id": "workbench_top",
        "entity_kind": "REGION",
        "function": "The surface where the workpiece sits and where tools are left.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["table surface", "desk top"],
        "required_properties": ["flat surface", "supports objects"]
      }
    ],
    "functional_relations": [
      {
        "id": "on_surface",
        "relation": "spatial",
        "participant_roles": ["workpiece", "workbench_top"],
        "required": true
      },
      {
        "id": "hidden_in",
        "relation": "spatial",
        "participant_roles": ["fastening_equipment", "storage_unit"],
        "required": true
      },
      {
        "id": "compatible_for",
        "relation": "functional",
        "participant_roles": ["fastening_equipment", "workpiece"],
        "required": true
      },
      {
        "id": "final_placement",
        "relation": "spatial",
        "participant_roles": ["fastening_equipment", "workbench_top"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search",
        "operation": "inspection",
        "participant_roles": ["storage_unit", "robot_arm"],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "manipulation",
        "participant_roles": ["fastening_equipment", "workpiece", "robot_arm"],
        "operation_count": 1
      },
      {
        "id": "place",
        "operation": "placement",
        "participant_roles": ["fastening_equipment", "workbench_top", "robot_arm"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workpiece": [
        {
          "label": "yellow_and_blue_object",
          "visual_description": "Yellow blocky object on a black mat on the table."
        }
      ],
      "workbench_top": [
        {
          "label": "wooden_table_surface",
          "visual_description": "Brown wooden table surface."
        }
      ],
      "storage_unit": [
        {
          "label": "left_drawer",
          "visual_description": "Blue drawer on the left side under the table."
        },
        {
          "label": "right_drawer",
          "visual_description": "Blue drawer on the right side under the table."
        },
        {
          "label": "standing_cabinet",
          "visual_description": "Blue tall cabinet behind the table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "left_drawer",
        "visual_description": "Blue drawer under table, closed, has handle.",
        "reason": "Closed storage structure likely containing tools."
      },
      {
        "id": "right_drawer",
        "label": "right_drawer",
        "visual_description": "Blue drawer under table, closed, has handle.",
        "reason": "Closed storage structure likely containing tools."
      },
      {
        "id": "standing_cabinet",
        "label": "standing_cabinet",
        "visual_description": "Blue tall cabinet behind table, closed, has handle.",
        "reason": "Closed storage structure likely containing tools."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "standing_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
